MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]

    children = [[]]
    stack = [0]

    for ch in s:
        if ch == "(":
            v = len(children)
            children.append([])
            children[stack[-1]].append(v)
            stack.append(v)
        else:
            stack.pop()

    nodes = len(children) - 1

    fact = [1] * (nodes + 1)
    for i in range(1, nodes + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (nodes + 1)
    invfact[nodes] = pow(fact[nodes], MOD - 2, MOD)
    for i in range(nodes, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    type_of = [-1] * (nodes + 1)
    type_size = []
    type_id = {}

    def get_type(child_types):
        key = tuple(sorted(child_types))
        if key in type_id:
            return type_id[key]

        ways = fact[len(key)]
        i = 0
        while i < len(key):
            j = i + 1
            while j < len(key) and key[j] == key[i]:
                j += 1
            cnt = j - i
            ways = ways * invfact[cnt] % MOD
            ways = ways * pow(type_size[key[i]], cnt, MOD) % MOD
            i = j

        tid = len(type_size)
        type_id[key] = tid
        type_size.append(ways)
        return tid

    for v in range(nodes, 0, -1):
        type_of[v] = get_type([type_of[c] for c in children[v]])

    root_types = sorted(type_of[c] for c in children[0])
    ans = fact[len(root_types)]

    i = 0
    while i < len(root_types):
        j = i + 1
        while j < len(root_types) and root_types[j] == root_types[i]:
            j += 1
        cnt = j - i
        ans = ans * invfact[cnt] % MOD
        ans = ans * pow(type_size[root_types[i]], cnt, MOD) % MOD
        i = j

    print(ans)

if __name__ == "__main__":
    main()
